{
 "quarter": "Q4 FY24",
 "callDate": "2024-05-17",
 "guidance": [
  {
   "metric": "capex",
   "statement": "Annual capex is estimated at around 3,000 crores over the next 5 years.",
   "quote": "The CAPEX plan for the next 5 years is estimated to be somewhere between 14,000 to 15,000 crores which translates into an average CAPEX of almost 3,000 crores on annual basis.",
   "page": 5,
   "horizon": "next 5 years",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "Manpower cost as a percentage of revenue is expected to drop to 16% in FY25.",
   "quote": "we expected to bring it down to further to 16% of revenue in the current financial year.",
   "page": 4,
   "horizon": "FY25",
   "quantitative": true
  },
  {
   "metric": "orders",
   "statement": "Around 47,000 crores of orders are expected to materialize in the next 6 months to 1 year.",
   "quote": "We expect almost 47,000 crores of orders to materialize in this 1-year timeframe.",
   "page": 6,
   "horizon": "next 6 months to 1 year",
   "quantitative": true
  },
  {
   "metric": "orders",
   "statement": "Outstanding order book is expected to reach around 1,20,000 crores by March 31, 2025.",
   "quote": "we expect the outstanding order book position to be somewhere around 1,20,000 crores even after liquidation",
   "page": 6,
   "horizon": "by March 31, 2025",
   "quantitative": true
  },
  {
   "metric": "orders",
   "statement": "Anticipated pipeline orders aggregate around 1,60,000 to 1,70,000 crores over 18 months to 3 years.",
   "quote": "The aggregate value of all these orders is expected to be somewhere around 1,60,000 to 1,70,000 crores and our expectation it will all materialize in the next 18 months to 3 years\u2019 time frame.",
   "page": 7,
   "horizon": "18 months to 3 years",
   "quantitative": true
  },
  {
   "metric": "margin",
   "statement": "EBITDA margins are expected to range between 29% and 33% over the next 2-3 years.",
   "quote": "at the minimum level it should be not less than 29%... should be somewhere around 32% to 33%.",
   "page": 10,
   "horizon": "next 2-3 years",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Manufacturing revenue growth is expected to be around 15% to 18% annually.",
   "quote": "the manufacturing growth definitely it has to be around 15% to 18% growth has to be there every year.",
   "page": 17,
   "horizon": "every year",
   "quantitative": true
  },
  {
   "metric": "revenue",
   "statement": "Repair and overhaul growth is expected to sustain around 9% to 10% annually.",
   "quote": "And the repair and overall growth of around 9% to 10% growth, we will be able to sustain",
   "page": 17,
   "horizon": "every year",
   "quantitative": true
  }
 ],
 "delivered": [
  {
   "metric": "revenue",
   "statement": "Revenue from operations reached 30,381 crores in FY24, registering a 13% increase.",
   "page": 3
  },
  {
   "metric": "margin",
   "statement": "Manpower cost as a percentage of revenue rationalized to 17% in FY24.",
   "page": 4
  },
  {
   "metric": "margin",
   "statement": "Overhead expenditure to revenue percentage was brought down to 4.66% in FY24.",
   "page": 4
  },
  {
   "metric": "orders",
   "statement": "Outstanding order book stood at 94,000 crores as of May 2024.",
   "page": 6
  },
  {
   "metric": "volume",
   "statement": "Delivered 5 LCA aircraft and 6 ALH helicopters during FY24.",
   "page": 9
  },
  {
   "metric": "revenue",
   "statement": "Development sales reached around 1,500 crores, accounting for about 5% of total revenue in FY24.",
   "page": 16
  }
 ],
 "tone": "Confident on robust order book, strong delivery pipeline, and sustained double-digit growth.",
 "pushback": [
  {
   "topic": "Gross Margin Sustainability",
   "gist": "Analysts questioned the drivers behind the surge in gross margins above 60% in Q4.",
   "page": 8
  },
  {
   "topic": "LCA Delivery Targets",
   "gist": "Analysts questioned if supply chain challenges would hinder the delivery target of 16 LCA Mark 1As.",
   "page": 13
  },
  {
   "topic": "LCA Mark 2 Weight",
   "gist": "An analyst raised concerns that LCA Mark 1A weight is higher than competing aircraft like the Gripen.",
   "page": 13
  },
  {
   "topic": "Call Frequency",
   "gist": "An analyst requested more frequent earnings calls, moving to semi-annual or quarterly interactions.",
   "page": 16
  }
 ]
}
